package com.bts.viewplustest.link; import com.bts.viewplustest.user.*; import jakarta.validation.*; import jakarta.validation.constraints.*; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/video-links") public class VideoLinkController {private final VideoLinkRepository links;private final UserRepository users;public VideoLinkController(VideoLinkRepository l,UserRepository u){links=l;users=u;}@GetMapping public List<Response> list(){return links.findAllByOrderByIdDesc().stream().map(this::r).toList();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Response add(Authentication a,@Valid @RequestBody Request q){URI u=URI.create(q.url());if(!"http".equals(u.getScheme())&&!"https".equals(u.getScheme()))throw new IllegalArgumentException("http 또는 https 링크만 가능합니다.");return r(links.save(new VideoLink(users.findById((Long)a.getPrincipal()).orElseThrow(),q.title().trim(),q.url())));}private Response r(VideoLink v){return new Response(v.getId(),v.getTitle(),v.getUrl(),v.getOwner().getNickname());}public record Request(@NotBlank @Size(max=120)String title,@NotBlank @Size(max=2048)String url){}public record Response(Long id,String title,String url,String ownerNickname){} }
